def solve(grads, counts):
    if len(grads)!=len(counts) or any(c<0 for c in counts):raise ValueError("invalid counts")
    if not grads:return []
    width=len(grads[0])
    if any(len(g)!=width for g in grads):raise ValueError("shape mismatch")
    total=sum(counts)
    if total<=0:raise ValueError("zero total")
    return [sum(g[j]*c for g,c in zip(grads,counts))/total for j in range(width)]
